import type { InspectionResponse } from './inspection-response-model';

export const EvidenceEvidenceTypeKeyToLabel = {
  'Photo': 'Photo',
  'Document': 'Document',
  'Receipt': 'Receipt',
  'InspectionRecord': 'Inspection Record',
  'Other': 'Other'
} as const;
export type EvidenceEvidenceTypeKey = keyof typeof EvidenceEvidenceTypeKeyToLabel;

export interface Evidence {
  /**
   * @displayName Evidence ID
   * @description Unique system identifier - GUID generated by system
   * @uiConstraints NEVER create input fields for this ID
   */
  id: string;
  /**
   * @displayName Evidence Name
   * @description Human-readable record identifier
   * @validationRule Required for create/update operations
   */
  evidenceName: string;
  /**
   * @displayName Caption
   */
  caption?: string;
  /**
   * @displayName Created Date
   * @validationRule Required for create/update operations
   */
  createdDate: string;
  /**
   * @displayName Evidence Type
   * @validationRule Required for create/update operations
   */
  evidenceTypeKey: EvidenceEvidenceTypeKey;
  /**
   * @displayName Evidence URL
   * @validationRule Required for create/update operations
   */
  evidenceURL: string;
  /**
   * @displayName File Name
   * @validationRule Required for create/update operations
   */
  fileName: string;
  /**
   * @displayName Inspection Response
   */
  inspectionResponse?: Pick<InspectionResponse, 'id' | 'inspectionResponseName'>;
  /**
   * @displayName Photo Data URL
   */
  photoDataURL?: string;
}

export const _Evidence = 'Evidence' as const;